#include <bits/stdc++.h>
#define err(args...) {}
#ifdef DEBUG
#include "_debug.cpp"
#include "callable.hpp/callable.hpp"
#endif
#define endl '\n'
using namespace std;
using ll = long long;
const int N = 10;
string maze[N];
int n_scientists[N][N] = {};
int n_rescue[N][N] = {};
int infect_time[N][N] = {};
int delta_x[] = {-1, 1, 0, 0};
int delta_y[] = {0, 0, -1, 1};
int reach_time[N][N][N][N] = {};
const int MAX_FLOW = 2 * N * N + 2;
const int INF = 1'000'000'000;
vector<int> adj[MAX_FLOW+1];
int capacity[MAX_FLOW][MAX_FLOW], flow[MAX_FLOW][MAX_FLOW], ptr[MAX_FLOW], dist[MAX_FLOW], parent[MAX_FLOW];

bool build_graph(int s, int t) {
    memset(dist, -1, sizeof dist);
    dist[s] = 0;
    queue<int> q;
    q.push(s);
    while(!q.empty()) {
        int u = q.front(); q.pop();
        for(auto v : adj[u]) {
            if(capacity[u][v] - flow[u][v] > 0 && dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return dist[t] != -1;
}

bool dfs_path(int u, int t) {
    if(u == t) return true;
    for(int& i = ptr[u]; i < (int)adj[u].size(); i++) {
        int v = adj[u][i];
        if(dist[v] == dist[u] + 1 && capacity[u][v] - flow[u][v] > 0 && dfs_path(v, t)) {
            parent[v] = u;
            return true;
        }
    }
    return false;
}

bool find_augmenting_path(int s, int t) {
    memset(parent, -1, sizeof parent);
    parent[s] = 0;
    return dfs_path(s, t);
}

void setup_network() {
    memset(capacity, 0, sizeof capacity);
    memset(flow, 0, sizeof flow);
}

void add_network_edge(int u, int v, int c) {
    adj[u].push_back(v);
    adj[v].push_back(u);
    capacity[u][v] += c;
}

int max_flow(int s, int t) {
    int total_flow = 0;
    while(build_graph(s, t)) {
        memset(ptr, 0, sizeof ptr);
        while(find_augmenting_path(s, t)) {
            int min_cap = INF;
            for(int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                min_cap = min(min_cap, capacity[u][v] - flow[u][v]);
            }
            for(int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                flow[u][v] += min_cap;
                flow[v][u] -= min_cap;
            }
            total_flow += min_cap;
        }
    }
    return total_flow;
}

int node_idx(int n, int i, int j, bool right_side) {
    return i * n + j + (right_side ? n * n : 0);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, t;
    cin >> n >> t;
    string line;
    pair<int,int> explosion_point;
    for(int i=0; i<n; i++) {
        cin >> line;
        for(int j=0; j<n; j++) {
            if(line[j] == 'Y') {
                maze[i][j] = 'Y';
            } else if(line[j] == 'Z') {
                maze[i][j] = 'Z';
                explosion_point = {i,j};
            } else {
                maze[i][j] = '.';
                n_scientists[i][j] += line[j] - '0';
            }
        }
    }
    for(int i=0; i<n; i++) {
        cin >> line;
        for(int j=0; j<n; j++) {
            if(line[j] != 'Y' && line[j] != 'Z') {
                n_rescue[i][j] += line[j] - '0';
            }
        }
    }
    memset(infect_time, -1, sizeof infect_time);
    infect_time[explosion_point.first][explosion_point.second] = 0;
    queue<pair<int,int>> q;
    q.push(explosion_point);
    while(!q.empty()) {
        int i = q.front().first, j = q.front().second;
        q.pop();
        for(int d=0; d<4; d++) {
            int ni = i + delta_x[d], nj = j + delta_y[d];
            if(0 <= ni && ni < n && 0 <= nj && nj < n && maze[ni][nj] == '.' && infect_time[ni][nj] == -1) {
                infect_time[ni][nj] = infect_time[i][j] + 1;
                q.push({ni, nj});
            }
        }
    }
    memset(reach_time, -1, sizeof reach_time);
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            if(maze[i][j] == '.') {
                reach_time[i][j][i][j] = 0;
                queue<pair<int,int>> q2;
                q2.push({i,j});
                while(!q2.empty()) {
                    int ii = q2.front().first, jj = q2.front().second;
                    q2.pop();
                    if(infect_time[ii][jj] == -1 || reach_time[i][j][ii][jj] < infect_time[ii][jj]) {
                        for(int d=0; d<4; d++) {
                            int ni = ii + delta_x[d], nj = jj + delta_y[d];
                            if(0 <= ni && ni < n && 0 <= nj && nj < n && maze[ni][nj] == '.' &&
                               (infect_time[ni][nj] == -1 || reach_time[i][j][ii][jj] + 1 <= infect_time[ni][nj]) &&
                               reach_time[i][j][ni][nj] == -1) {
                                reach_time[i][j][ni][nj] = reach_time[i][j][ii][jj] + 1;
                                q2.push({ni, nj});
                            }
                        }
                    }
                }
            }
        }
    }
    int s_node = 2 * n * n, t_node = 2 * n * n + 1;
    setup_network();
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            if(n_scientists[i][j]) {
                add_network_edge(s_node, node_idx(n, i, j, false), n_scientists[i][j]);
            }
            if(n_rescue[i][j]) {
                add_network_edge(node_idx(n, i, j, true), t_node, n_rescue[i][j]);
            }
            for(int ii=0; ii<n; ii++) {
                for(int jj=0; jj<n; jj++) {
                    if(0 <= reach_time[i][j][ii][jj] && reach_time[i][j][ii][jj] <= t) {
                        add_network_edge(node_idx(n, i, j, false), node_idx(n, ii, jj, true), INF);
                    }
                }
            }
        }
    }
    cout << max_flow(s_node, t_node) << endl;
    return 0;
}
